"""Tests for render.py (and collect.sh, when a veyra binary is available).

    python3 -m unittest discover -s .github/actions/veyra-review/tests

fixtures/pr holds real Veyra 1.1 output: a branch with a migration, a Dockerfile, a signed commit,
a commit signed by an untrusted key, unsigned commits, a structural merge and an Assisted-by trailer.
"""

import io
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import unittest
from contextlib import redirect_stdout

HERE = os.path.dirname(os.path.abspath(__file__))
ACTION = os.path.dirname(HERE)
REPO = os.path.dirname(os.path.dirname(os.path.dirname(ACTION)))
FIXTURE = os.path.join(HERE, "fixtures", "pr")
sys.path.insert(0, ACTION)

import render  # noqa: E402


def write_json(directory, name, value):
    with open(os.path.join(directory, name + ".json"), "w", encoding="utf-8") as f:
        json.dump(value, f)


class Fixture(unittest.TestCase):
    """A writable copy of fixtures/pr for each test."""

    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.dir = os.path.join(self.tmp, "pr")
        shutil.copytree(FIXTURE, self.dir)

    def tearDown(self):
        shutil.rmtree(self.tmp, ignore_errors=True)

    def render(self, **kwargs):
        return render.render(self.dir, **kwargs)

    def section(self, md, title):
        start = md.index(title)
        end = md.find("\n### ", start + 1)
        return md[start : end if end != -1 else len(md)]


class FullReview(Fixture):
    def test_marker_and_risk_header_come_first(self):
        md, _ = self.render()
        lines = md.splitlines()
        self.assertEqual(lines[0], render.MARKER)
        self.assertEqual(lines[1], "## 🔴 Veyra review: high risk")
        self.assertIn("`main` → `435978c`", md)
        self.assertIn("5 commits", md)
        self.assertIn("risk score 18", md)
        self.assertIn("- touches a CI pipeline", md)

    def test_overview_counts(self):
        md, _ = self.render()
        self.assertIn("| Analyzer findings | 🔴 2 high, ⚪ 1 low |", md)
        self.assertIn("| Tests to run | 3 |", md)
        self.assertIn("| May be affected | 5 files (3 high confidence) |", md)
        self.assertIn("| Changed symbols | 3 in 1 file |", md)
        self.assertIn("| Signatures | 1 good · 1 unverified · 3 unsigned · 0 bad |", md)
        self.assertIn("| Structural merges | 1 commit |", md)

    def test_findings_are_sorted_by_severity_with_location_and_advice(self):
        md, _ = self.render()
        findings = self.section(md, "### Analyzer findings")
        rows = [l for l in findings.splitlines() if l.startswith("| 🔴") or l.startswith("| ⚪")]
        self.assertEqual(len(rows), 3)
        self.assertTrue(rows[0].startswith("| 🔴 high | `migrations/001.sql:1` | drops a column"))
        self.assertIn("<br>`ALTER TABLE users DROP COLUMN email;`", rows[0])
        self.assertIn("`drop-column`", rows[0])
        self.assertTrue(rows[0].endswith("| stop reading/writing it in a release before, then drop |"))
        self.assertTrue(rows[2].startswith("| ⚪ low | `Dockerfile:1` |"))

    def test_tests_and_dependents_with_evidence(self):
        md, _ = self.render()
        tests = self.section(md, "### Tests to run")
        self.assertIn("- `crates/veyra-cli/tests/cli.rs` — changed in this change", tests)
        self.assertIn("<b>May be affected: 5 files (3 high, 2 medium confidence)</b>", md)
        self.assertIn("- 🔴 **high** `crates/veyra-cli/src/cmd/ai.rs`", md)
        self.assertIn("  - imports crates/veyra-core/src/index.rs (`veyra_core::diff`, line 13)", md)
        # At most three pieces of evidence per dependent, like the CLI.
        self.assertIn("  - …and 2 more", md)

    def test_changed_symbols_with_lines_and_unsupported_files(self):
        md, _ = self.render()
        self.assertIn("**`lib.rs`** · Rust", md)
        self.assertIn("- `~` function `a` — modified (line 1)", md)
        self.assertIn("- `+` function `c` — added", md)

    def test_commits_signatures_and_trailers(self):
        md, _ = self.render()
        commits = self.section(md, "### Commits")
        self.assertIn("**Merged structurally by Veyra**", commits)
        self.assertIn("- `e150c7f`: `lib.rs`", commits)
        self.assertIn("| ✅ good (ssh, t@​e.x) |", commits)
        self.assertIn("| ⚠️ unverified key (ssh), trust undefined |", commits)
        self.assertIn("Veyra-Structural-Merge: lib.rs", commits)
        self.assertIn("Assisted-by: Claude Opus 5.5", commits)
        self.assertEqual(commits.count("| unsigned |"), 3)

    def test_co_changes_limitations_and_footer(self):
        md, _ = self.render()
        self.assertIn("- `crates/veyra-cli/src/cli.rs` — in 8 of 10 commits", md)
        self.assertIn("<summary>Limitations of this analysis</summary>", md)
        self.assertIn("Generated by veyra 1.1.0", md)

    def test_outputs(self):
        _, outputs = self.render()
        self.assertEqual(
            outputs,
            {
                "risk": "high",
                "risk-score": "18",
                "findings": "3",
                "high-findings": "2",
                "medium-findings": "0",
                "low-findings": "1",
                "tests": "3",
                "unsigned-commits": "3",
                "unverified-signatures": "1",
                "bad-signatures": "0",
            },
        )

    def test_cli_writes_markdown_and_github_output(self):
        out_file = os.path.join(self.tmp, "github_output")
        buf = io.TextIOWrapper(io.BytesIO(), encoding="utf-8")
        with redirect_stdout(buf):
            self.assertEqual(render.main([self.dir, "--github-output", out_file]), 0)
        buf.seek(0)
        self.assertTrue(buf.read().startswith(render.MARKER + "\n"))
        with open(out_file, encoding="utf-8") as f:
            lines = f.read().splitlines()
        self.assertIn("risk=high", lines)
        self.assertIn("high-findings=2", lines)

    def test_cli_summary_file_is_never_shortened(self):
        summary = os.path.join(self.tmp, "summary.md")
        buf = io.TextIOWrapper(io.BytesIO(), encoding="utf-8")
        with redirect_stdout(buf):
            render.main([self.dir, "--max-chars", "2500", "--summary", summary])
        buf.seek(0)
        comment = buf.read()
        with open(summary, encoding="utf-8") as f:
            full = f.read()
        self.assertIn("omitted to fit GitHub's comment size limit", comment)
        self.assertNotIn("omitted", full)
        self.assertEqual(full, self.render()[0])


class UntrustedText(Fixture):
    """Commit messages, paths and excerpts come from the pull request."""

    def test_no_second_marker_no_html_no_mentions(self):
        md, _ = self.render()
        self.assertEqual(md.count(render.MARKER), 1)
        self.assertNotIn("@octocat", md)
        self.assertIn("@​octocat", md)
        self.assertIn("&lt;\\!-- veyra-review --&gt;", md)

    def test_pipes_dont_break_table_rows(self):
        md, _ = self.render()
        row = next(l for l in md.splitlines() if "change b" in l)
        unescaped = re.findall(r"(?<!\\)\|", row)
        self.assertEqual(len(unescaped), 5, row)

    def test_code_spans_survive_backticks(self):
        self.assertEqual(render.code("a`b"), "``a`b``")
        self.assertEqual(render.code("`x`"), "`` `x` ``")
        self.assertEqual(render.code("a|b", table=True), "`a\\|b`")

    def test_markdown_in_summaries_is_literal(self):
        self.assertEqual(render.text("**[x](y)** `z`"), "\\*\\*\\[x\\](y)\\*\\* \\`z\\`")

    def test_excerpt_with_marker_stays_in_code(self):
        write_json(
            self.dir,
            "analyze",
            [{"area": "custom", "severity": "medium", "rule": "r", "path": "a|b.sql", "line": 3,
              "message": "m", "advice": "", "excerpt": "<!-- veyra-review --> @x"}],
        )
        md, _ = self.render()
        # Inert inside a code span: the action only matches comments that start with the marker.
        self.assertIn("<br>`<!-- veyra-review --> @x`", md)
        self.assertIn("`a\\|b.sql:3`", md)


class Degraded(Fixture):
    def test_a_failed_analysis_is_reported_and_the_rest_renders(self):
        os.remove(os.path.join(self.dir, "impact.json"))
        with open(os.path.join(self.dir, "impact.err"), "w") as f:
            f.write("error: HEAD has no common history with main\n")
        md, outputs = self.render()
        self.assertIn("## Veyra review\n", md)
        self.assertIn("_`veyra impact` is unavailable:_", md)
        self.assertIn("HEAD has no common history with main", md)
        self.assertIn("### Analyzer findings", md)
        self.assertIn("- `+` function `c` — added", md)
        self.assertEqual(outputs["risk"], "")
        self.assertEqual(outputs["findings"], "3")

    def test_symbols_fall_back_to_impact_when_semantic_diff_fails(self):
        os.remove(os.path.join(self.dir, "semantic.json"))
        with open(os.path.join(self.dir, "semantic.err"), "w") as f:
            f.write("boom")
        md, _ = self.render()
        self.assertIn("function `concurrent_veyra_commands_serialize_through_the_journal_lock` — added", md)
        self.assertNotIn("boom", md)

    def test_unparsable_output_shows_its_stderr(self):
        with open(os.path.join(self.dir, "analyze.json"), "w") as f:
            f.write("[{")
        with open(os.path.join(self.dir, "analyze.err"), "w") as f:
            f.write("error: --fail-on takes high, medium or low")
        md, outputs = self.render()
        self.assertIn("_`veyra analyze` is unavailable:_", md)
        self.assertIn("--fail-on takes high, medium or low", md)
        self.assertEqual(outputs["findings"], "0")

    def test_no_changes(self):
        write_json(self.dir, "impact", {"changed_files": [], "dependents": [], "tests": [], "co_changes": [],
                                        "risk": {"level": "low", "score": 0, "reasons": []}, "limitations": []})
        md, _ = self.render()
        self.assertIn("No changes between the base and the head.", md)
        self.assertNotIn("### Analyzer findings", md)

    def test_nothing_collected_at_all(self):
        empty = os.path.join(self.tmp, "empty")
        os.mkdir(empty)
        md, outputs = render.render(empty)
        self.assertTrue(md.startswith(render.MARKER))
        self.assertIn("_`veyra analyze` is unavailable:_", md)
        self.assertIn("not run", md)
        self.assertEqual(outputs["risk"], "")


class Limits(Fixture):
    def test_fits_the_comment_size_limit_by_dropping_details(self):
        md, _ = self.render(max_chars=2500)
        self.assertLessEqual(len(md), 2500)
        self.assertIn("omitted to fit GitHub's comment size limit", md)
        # The header, overview and findings are never dropped.
        self.assertIn("## 🔴 Veyra review: high risk", md)
        self.assertIn("| 🔴 high | `migrations/001.sql:1`", md)

    def test_hard_truncation_as_a_last_resort(self):
        md, _ = self.render(max_chars=600)
        self.assertLessEqual(len(md), 600)
        self.assertTrue(md.startswith(render.MARKER))
        self.assertIn("truncated", md)

    def test_long_histories_list_only_flagged_commits(self):
        commits, verify = [], []
        for i in range(40):
            oid = "%040x" % i
            commits.append([{"id": oid, "summary": "commit %d" % i, "trailers": []}])
            verify.append({"object": oid, "signed": i == 7, "valid": False, "status": "bad" if i == 7 else None})
        with open(os.path.join(self.dir, "commits.json"), "w") as f:
            f.write("\n".join(json.dumps(c) for c in commits))
        with open(os.path.join(self.dir, "verify.json"), "w") as f:
            f.write("\n".join(json.dumps(v) for v in verify))
        with open(os.path.join(self.dir, "meta.txt"), "a") as f:
            f.write("commits=300\n")
        md, outputs = self.render()
        commits_md = self.section(md, "### Commits")
        self.assertIn("Showing the 1 commit with a bad signature or a structural merge.", commits_md)
        self.assertIn("| ❌ bad |", commits_md)
        self.assertNotIn("commit 8", commits_md)
        self.assertIn("Only the newest 40 of 300 commits were checked.", commits_md)
        self.assertIn("❌ 0 good · 39 unsigned · 1 bad", md)
        self.assertEqual(outputs["bad-signatures"], "1")


class Parsing(unittest.TestCase):
    def test_stream_of_values(self):
        self.assertEqual(render.parse_stream('[1]\n{"a": 2}\n\n[]  '), [[1], {"a": 2}, []])
        self.assertEqual(render.parse_stream(""), [])


def veyra_binary():
    if os.environ.get("VEYRA"):
        return os.environ["VEYRA"]
    for name in ("veyra.exe", "veyra"):
        for profile in ("debug", "release"):
            path = os.path.join(REPO, "target", profile, name)
            if os.path.isfile(path):
                return path
    return shutil.which("veyra")


def bash_binary():
    """Git Bash on Windows (System32's bash.exe is WSL, which sees a different filesystem)."""
    if os.name != "nt":
        return shutil.which("bash")
    git = shutil.which("git")
    if git:
        root = os.path.dirname(os.path.dirname(git))
        for candidate in (os.path.join(root, "bin", "bash.exe"), os.path.join(os.path.dirname(root), "bin", "bash.exe")):
            if os.path.isfile(candidate):
                return candidate
    return None


@unittest.skipUnless(veyra_binary() and bash_binary() and shutil.which("git"), "needs veyra, bash and git")
class CollectEndToEnd(unittest.TestCase):
    """collect.sh against a real repository, then render.py on what it wrote."""

    def test_collect_then_render(self):
        tmp = tempfile.mkdtemp()
        try:
            repo, out = os.path.join(tmp, "repo"), os.path.join(tmp, "out")
            env = dict(os.environ, VEYRA=veyra_binary(), GIT_AUTHOR_NAME="T", GIT_AUTHOR_EMAIL="t@example.com",
                       GIT_COMMITTER_NAME="T", GIT_COMMITTER_EMAIL="t@example.com")

            def git(*args):
                subprocess.run(["git", *args], cwd=repo, env=env, check=True, capture_output=True)

            def write(path, content):
                full = os.path.join(repo, path)
                os.makedirs(os.path.dirname(full), exist_ok=True)
                with open(full, "w", newline="\n") as f:
                    f.write(content)

            os.mkdir(repo)
            git("init", "-q", "-b", "main")
            write("lib.rs", "fn a() {}\n")
            git("add", ".")
            git("commit", "-qm", "init")
            git("switch", "-qc", "feat")
            write("lib.rs", "fn a() { b() }\nfn b() {}\n")
            write("migrations/001.sql", "ALTER TABLE users DROP COLUMN email;\n")
            git("add", ".")
            git("commit", "-qm", "feat: drop email")

            script = os.path.join(ACTION, "collect.sh").replace("\\", "/")
            subprocess.run([bash_binary(), script, "main", out.replace("\\", "/")], cwd=repo, env=env, check=True)
            md, outputs = render.render(out)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)
        self.assertIn("| 🔴 high | `migrations/001.sql:1`", md)
        self.assertIn("- `+` function `b` — added (line 2)", md)
        self.assertIn("1 commit", md)
        self.assertEqual(outputs["high-findings"], "1")
        self.assertEqual(outputs["unsigned-commits"], "1")


if __name__ == "__main__":
    unittest.main()
